#!/bin/bash\n\n# Deployment Monitor Script\n# Monitors the deployment progress and provides real-time status\n\nset +e\n\nPROJECT_DIR=\"/Users/ajaydwivedi/Documents/Github/Personal/PostgreSQL-Learning/Debezium-CDC-Kafka\"\ncd \"$PROJECT_DIR\"\n\necho \"🔍 Debezium CDC Deployment Monitor\"\necho \"===================================\"\necho \"\"\n\n# Function to check container status\ncheck_containers() {\n    echo \"📦 Container Status:\"\n    echo \"─────────────────────\"\n    docker ps --format \"table {{.Names}}\\t{{.Status}}\" 2>/dev/null | grep -i cdc || echo \"No CDC containers running yet\"\n    echo \"\"\n}\n\n# Function to check logs\ncheck_logs() {\n    echo \"📋 Recent Deployment Logs:\"\n    echo \"─────────────────────────\"\n    if [ -f \"deployment_output.txt\" ]; then\n        tail -30 deployment_output.txt\n    elif ls deployment_*.log > /dev/null 2>&1; then\n        tail -30 $(ls -t deployment_*.log | head -1)\n    else\n        echo \"No deployment logs found yet\"\n    fi\n    echo \"\"\n}\n\n# Function to check network\ncheck_network() {\n    echo \"🌐 Docker Network:\"\n    echo \"──────────────────\"\n    docker network ls 2>/dev/null | grep cdc-network || echo \"cdc-network not created yet\"\n    echo \"\"\n}\n\n# Function to check ports\ncheck_ports() {\n    echo \"🔌 Port Status:\"\n    echo \"───────────────\"\n    echo \"Kafka UI (8080): $(nc -z localhost 8080 2>&1 && echo '✅ OPEN' || echo '❌ CLOSED')\"\n    echo \"Debezium (8083): $(nc -z localhost 8083 2>&1 && echo '✅ OPEN' || echo '❌ CLOSED')\"\n    echo \"pgAdmin (5050): $(nc -z localhost 5050 2>&1 && echo '✅ OPEN' || echo '❌ CLOSED')\"\n    echo \"PostgreSQL (5433): $(nc -z localhost 5433 2>&1 && echo '✅ OPEN' || echo '❌ CLOSED')\"\n    echo \"\"\n}\n\n# Display real-time status\nwhile true; do\n    clear\n    echo \"🚀 Deployment Status Monitor\"\n    echo \"=============================\"\n    echo \"Time: $(date)\"\n    echo \"\"\n    \n    check_containers\n    check_network\n    check_ports\n    check_logs\n    \n    echo \"Press Ctrl+C to exit\"\n    sleep 10\ndone\n"
